    document.body.appendChild(menuEl); const r = anchor.getBoundingClientRect(); const mh = menuEl.offsetHeight, mw = menuEl.offsetWidth;
    menuEl.style.left = clamp(r.left, 8, innerWidth - mw - 8) + 'px'; menuEl.style.top = (r.top - mh - 6 > 8 ? r.top - mh - 6 : r.bottom + 6) + 'px';
    setTimeout(() => addEventListener('pointerdown', outside, true), 0);
    const f = menuEl.querySelector('button:not([disabled])'); if (f) f.focus();
