    for (const [r, names] of Object.entries(regions)) { const g = document.createElement('optgroup'); g.label = (c.ch.regionLabels && c.ch.regionLabels[r]) || r; for (const n of names) g.appendChild(new Option(n.replace(/_/g, ' '), n)); sel.appendChild(g); }
